def transforms(pts,h,w):
    res={}
    res['id']={(r,c) for r,c in pts}
    res['fliplr']={(r,w-1-c) for r,c in pts}
    res['flipud']={(h-1-r,c) for r,c in pts}
    res['rot180']={(h-1-r,w-1-c) for r,c in pts}
    res['transpose']={(c,r) for r,c in pts}
    res['antitranspose']={(w-1-c,h-1-r) for r,c in pts}
    return res
